using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static partial class HedgeDetailUpdater {
static void PalmThicken(){var sc=SceneManager.GetActiveScene();if(sc.path!="Assets/Scenes/Oasis/MobileOptimization/Gangstar City.unity")throw new Exception("Wrong scene");string folder="Assets/Scenes/Oasis/PalmTrunkDetail";Directory.CreateDirectory(folder);AssetDatabase.Refresh();var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/Palm.prefab");var original=prefab.GetComponent<MeshFilter>().sharedMesh;var all=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.sharedMesh&&f.GetComponent<Renderer>()&&f.GetComponent<Renderer>().sharedMaterials.Any(m=>m&&m.name=="PalmBark_Mat")).ToArray();var sources=all.Select(f=>f.sharedMesh).Append(original).Distinct().ToArray();var map=new Dictionary<Mesh,Mesh>();foreach(var source in sources){if(AssetDatabase.GetAssetPath(source).Contains("PalmTrunkDetail"))continue;var data=Read(source);var p=F<Vector3[]>(data,"p");float min=p.Min(v=>v.y),max=p.Max(v=>v.y);var centers=new Dictionary<int,Vector2>();foreach(var group in p.GroupBy(v=>Mathf.Clamp(Mathf.FloorToInt((v.y-min)/(max-min)*40),0,39)))centers[group.Key]=new Vector2((group.Min(v=>v.x)+group.Max(v=>v.x))*.5f,(group.Min(v=>v.z)+group.Max(v=>v.z))*.5f);var changed=p.Select(v=>{int bin=Mathf.Clamp(Mathf.FloorToInt((v.y-min)/(max-min)*40),0,39);var center=centers[bin];return new Vector3(center.x+(v.x-center.x)*1.55f,v.y,center.y+(v.z-center.y)*1.55f);}).ToArray();var mesh=new Mesh{name=source.name+" Thicker Trunk",indexFormat=source.indexFormat};mesh.vertices=changed;mesh.normals=F<Vector3[]>(data,"normal");var tangent=F<Vector4[]>(data,"tangent");if(tangent!=null)mesh.tangents=tangent;var channels=F<Vector2[][]>(data,"uv");for(int c=0;c<8;c++)if(channels[c]!=null)mesh.SetUVs(c,channels[c]);var color=F<Color[]>(data,"colors");if(color!=null)mesh.colors=color;mesh.triangles=F<int[]>(data,"ids");mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();string path=folder+"/Trunk "+map.Count+".asset";AssetDatabase.CreateAsset(mesh,path);map[source]=mesh;}
int count=0;foreach(var f in all)if(map.TryGetValue(f.sharedMesh,out var mesh)){f.sharedMesh=mesh;EditorUtility.SetDirty(f);PrefabUtility.RecordPrefabInstancePropertyModifications(f);count++;}if(map.TryGetValue(original,out var rootMesh)){var contents=PrefabUtility.LoadPrefabContents("Assets/Scenes/Oasis/3D/Prefeb/Palm.prefab");contents.GetComponent<MeshFilter>().sharedMesh=rootMesh;foreach(var c in contents.GetComponentsInChildren<MeshCollider>(true))if(map.TryGetValue(c.sharedMesh,out var cm))c.sharedMesh=cm;PrefabUtility.SaveAsPrefabAsset(contents,"Assets/Scenes/Oasis/3D/Prefeb/Palm.prefab");PrefabUtility.UnloadPrefabContents(contents);}foreach(var c in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshCollider>(true)))if(c.sharedMesh&&map.TryGetValue(c.sharedMesh,out var cm)){c.sharedMesh=cm;PrefabUtility.RecordPrefabInstancePropertyModifications(c);}foreach(var group in all.Select(f=>f.GetComponentInParent<LODGroup>()).Where(g=>g).Distinct())group.RecalculateBounds();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/PalmTrunkDetail.txt","SUCCESS trunk diameter +55%, shared Palm prefab and "+count+" matching trunk renderers including scene LOD meshes updated; height, foliage, placements and vertex/triangle counts unchanged. Shared existing bark material retained.");var site=sc.GetRootGameObjects().FirstOrDefault(g=>g.name=="Median880 Rounded Railing");if(site){var at=site.transform.position+Vector3.up*4;var eye=site.transform.position+new Vector3(10,7,13);typeof(FinalPNGCityDetails).GetMethod("Capture",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static).Invoke(null,new object[]{sc,eye,at,"Palm-Trunk-Thicker"});}}
